import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'training-store',
  description:
    "Read and update the training tracker: people.json (who works here and their role), courses.json (each course, how long it stays valid and who needs it), completions.json (completions with expiry dates, and bookings) and quizzes.json. action:'status' for who needs what, by course, lapsed first; 'add_person' and 'add_course' to add or update one (an existing name or title is updated, never duplicated); 'complete' to record a completion; 'book' to book a session; 'save_quiz' to save a quiz; 'list' for everyone's training.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'add_person', 'add_course', 'complete', 'book', 'save_quiz', or 'list'.",
      required: true,
    },
    name: { type: 'string', description: "For add_person: the person's full name." },
    role: { type: 'string', description: "For add_person: their job, e.g. 'Barista'. It decides which courses they need." },
    startedAt: { type: 'string', description: "For add_person: their first day, YYYY-MM-DD or a weekday like 'monday'." },
    personStatus: { type: 'string', description: "For add_person: active, or left when someone leaves." },
    title: { type: 'string', description: "For add_course: the course's title. For save_quiz: the quiz's title." },
    validMonths: { type: 'number', description: 'For add_course: months a completion stays valid; 0 when it never expires.' },
    requiredFor: { type: 'string', description: "For add_course: 'everyone', or the roles that need it, e.g. 'barista, cook'." },
    provider: { type: 'string', description: 'For add_course: who runs or certifies it.' },
    person: { type: 'string', description: "Person id (e.g. 'p-3') or name; several names separated by commas." },
    course: { type: 'string', description: "Course id (e.g. 'c-2') or title." },
    completedAt: { type: 'string', description: 'For complete: the day it was finished, YYYY-MM-DD; default today.' },
    certificate: { type: 'string', description: 'For complete: the certificate or reference number exactly as given.' },
    on: { type: 'string', description: "For book: the session date, YYYY-MM-DD or a weekday like 'thursday'." },
    everyoneDue: {
      type: 'boolean',
      description: 'For book: true books everyone whose certificate for the course has lapsed, runs out within the window, or was never done.',
    },
    source: { type: 'string', description: "For save_quiz: the document it was written from, e.g. 'docs/opening-checklist.md'." },
    questions: {
      type: 'string',
      description: "For save_quiz: one question per line, 'Question? | right answer | wrong answer | wrong answer'.",
    },
    note: { type: 'string', description: 'Anything else worth keeping.' },
    withinDays: { type: 'number', description: 'How many days ahead count as due (default 30).' },
  },
  outputs: {
    expired: { type: 'number', description: 'Required certificates that have lapsed.' },
    expiringSoon: { type: 'number', description: 'Required certificates that run out within the window.' },
    missing: { type: 'number', description: 'Required courses never done.' },
    people: { type: 'number', description: 'People on the tracker.' },
    summary: { type: 'string', description: 'What changed, then who needs what, or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write', 'reminders'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── training-rules-start ──
// Pure derivations: dates in local calendar days, record matching, who needs
// which course, each person-course cell, the picture the crew reads, and quiz
// parsing. Kept self-contained between these sentinels so tests execute the
// shipped bytes.
var DAY_MS = 86400000;
var WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
var MONTH_KEYS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function noon(day) {
  return new Date(String(day).slice(0, 10) + 'T12:00:00');
}
function addDays(day, n) {
  var d = noon(day);
  d.setDate(d.getDate() + n);
  return localDay(d.getTime());
}
function addMonths(day, months) {
  var d = noon(day);
  var date = d.getDate();
  d.setDate(1);
  d.setMonth(d.getMonth() + months);
  // The 31st rolls to the last day of a shorter month, not into the next one.
  d.setDate(Math.min(date, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()));
  return localDay(d.getTime());
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
function dayName(day) {
  return WEEKDAYS[noon(day).getDay()];
}
function parseDay(text, nowMs, direction) {
  var raw = String(text == null ? '' : text).trim().toLowerCase().replace(/[.,]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!raw) return null;
  var iso = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:t.*)?$/);
  if (iso) return iso[1] + '-' + pad(Number(iso[2])) + '-' + pad(Number(iso[3]));
  var today = localDay(nowMs);
  if (raw === 'today' || raw === 'now') return today;
  if (raw === 'tomorrow') return addDays(today, 1);
  if (raw === 'yesterday') return addDays(today, -1);
  var rel = raw.match(/^(?:in )?(\d{1,3}) (day|days|week|weeks)( ago| from now)?$/);
  if (rel) {
    var n = Number(rel[1]) * (rel[2].charAt(0) === 'w' ? 7 : 1);
    return addDays(today, rel[3] === ' ago' ? -n : n);
  }
  var wd = raw.match(/^(this |next |last |on |coming )?(sun|mon|tue|wed|thu|fri|sat)[a-z]*$/);
  if (wd) {
    var target = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'].indexOf(wd[2]);
    var now = noon(today).getDay();
    if (direction === 'past' || wd[1] === 'last ') {
      var back = (now - target + 7) % 7;
      return addDays(today, -(wd[1] === 'last ' && back === 0 ? 7 : back));
    }
    if (wd[1] === 'this ') return addDays(today, (target - now + 7) % 7);
    return addDays(today, ((target - now + 6) % 7) + 1);
  }
  var md = raw.match(/^(?:[a-z]+day )?([a-z]{3,9}) (\d{1,2})(?:st|nd|rd|th)?(?: (\d{4}))?$/);
  var dm = raw.match(/^(?:[a-z]+day )?(\d{1,2})(?:st|nd|rd|th)? (?:of )?([a-z]{3,9})(?: (\d{4}))?$/);
  var parts = md ? { month: md[1], date: md[2], year: md[3] } : dm ? { month: dm[2], date: dm[1], year: dm[3] } : null;
  if (parts) {
    var m = MONTH_KEYS.indexOf(parts.month.slice(0, 3));
    if (m < 0) return null;
    var date = Number(parts.date);
    if (date < 1 || date > 31) return null;
    if (parts.year) return parts.year + '-' + pad(m + 1) + '-' + pad(date);
    var year = noon(today).getFullYear();
    var guess = year + '-' + pad(m + 1) + '-' + pad(date);
    var d = daysLeft(guess, nowMs);
    if (direction === 'past' && d > 0) guess = year - 1 + guess.slice(4);
    if (direction !== 'past' && d < 0) guess = year + 1 + guess.slice(4);
    return guess;
  }
  return null;
}
function matches(records, text, labelOf) {
  var wanted = String(text == null ? '' : text).trim().toLowerCase().replace(/['\u2019]s\b/g, '').replace(/\s+/g, ' ');
  if (!wanted) return [];
  var tiers = [
    function (r) { return String(r.id).toLowerCase() === wanted; },
    function (r) { return labelOf(r).toLowerCase() === wanted; },
    function (r) { return labelOf(r).toLowerCase().indexOf(wanted) === 0; },
    function (r) { return (' ' + labelOf(r).toLowerCase() + ' ').indexOf(' ' + wanted + ' ') >= 0; },
    function (r) { return labelOf(r).toLowerCase().indexOf(wanted) >= 0; },
    function (r) { var l = labelOf(r).toLowerCase(); return l.length >= 3 && wanted.indexOf(l) >= 0; },
  ];
  for (var i = 0; i < tiers.length; i++) {
    var hit = records.filter(tiers[i]);
    if (hit.length) return hit;
  }
  return [];
}
function describe(records, labelOf) {
  return records.map(function (r) { return r.id + ' ' + labelOf(r); }).join(', ');
}
function splitList(text) {
  var raw = String(text == null ? '' : text).trim();
  if (/^\[/.test(raw)) {
    try {
      var parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed.map(function (s) { return String(s).trim(); }).filter(Boolean);
    } catch (e) {
      // Not JSON after all; split it as text.
    }
  }
  return raw
    .split(/\s*[,;\n]+\s*/)
    .map(function (s) { return s.replace(/^(and|or|plus)\s+/i, '').replace(/[.\s]+$/, '').trim(); })
    .filter(Boolean);
}
function roleKey(text) {
  return String(text == null ? '' : text)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .replace(/([a-z]{3,}[^s])s$/, '$1');
}
function requires(course, person) {
  var rf = String((course.fields && course.fields.requiredFor) || 'everyone').toLowerCase();
  if (!rf.trim() || /\b(everyone|everybody|all|whole team|all staff)\b/.test(rf)) return true;
  var mine = roleKey(person.fields && person.fields.role);
  if (!mine) return false;
  return splitList(rf).map(roleKey).some(function (r) {
    return r && (r === mine || mine.indexOf(r) >= 0 || r.indexOf(mine) >= 0);
  });
}
function eventsFor(events, kind, personId, courseId) {
  return events.filter(function (e) {
    return e.kind === kind && e.data && e.data.personId === personId && e.data.courseId === courseId;
  });
}
function cell(person, course, events, nowMs, windowDays) {
  var done = eventsFor(events, 'completed', person.id, course.id).sort(function (a, b) {
    return String(a.data.completedAt).localeCompare(String(b.data.completedAt));
  });
  var last = done.length ? done[done.length - 1] : null;
  // A booking made before the latest completion was recorded is used up by it.
  var since = last ? String(last.at) : '';
  var booking = eventsFor(events, 'booked', person.id, course.id)
    .filter(function (e) { return daysLeft(e.data.on, nowMs) >= 0 && String(e.at) > since; })
    .sort(function (a, b) { return String(a.data.on).localeCompare(String(b.data.on)); })[0] || null;
  var required = requires(course, person);
  var expiresAt = last ? last.data.expiresAt || null : null;
  var days = expiresAt ? daysLeft(expiresAt, nowMs) : null;
  var state;
  if (last) state = !expiresAt ? 'done' : days < 0 ? 'expired' : days <= windowDays ? 'expiring' : 'current';
  else state = required ? 'missing' : 'optional';
  if (!required && (state === 'expired' || state === 'expiring')) state = 'optional';
  return { state: state, required: required, last: last, booking: booking, expiresAt: expiresAt, days: days };
}
function needText(person, c, nowMs) {
  var f = person.fields || {};
  var starts = f.startedAt && daysLeft(f.startedAt, nowMs) > 0 ? ', starts ' + f.startedAt : '';
  var what =
    c.state === 'expired'
      ? 'lapsed ' + c.expiresAt + ', ' + -c.days + (c.days === -1 ? ' day ago' : ' days ago')
      : c.state === 'expiring'
        ? 'runs out ' + c.expiresAt + ', ' + (c.days === 0 ? 'today' : 'in ' + c.days + (c.days === 1 ? ' day' : ' days'))
        : 'never done';
  return f.name + ' (' + person.id + starts + ') ' + what + (c.booking ? ', booked ' + dayName(c.booking.data.on) + ' ' + c.booking.data.on : '');
}
function needs(people, course, events, nowMs, windowDays) {
  var rank = { expired: 0, missing: 1, expiring: 2 };
  return people
    .map(function (p) { return { person: p, cell: cell(p, course, events, nowMs, windowDays) }; })
    .filter(function (x) { return x.cell.required && rank[x.cell.state] !== undefined; })
    .sort(function (a, b) {
      return rank[a.cell.state] - rank[b.cell.state] || (a.cell.days === null ? 0 : a.cell.days) - (b.cell.days === null ? 0 : b.cell.days);
    });
}
function validity(course) {
  var m = Number(course.fields.validMonths) || 0;
  return m ? 'every ' + m + ' months' : 'once';
}
function picture(people, courses, events, nowMs, windowDays) {
  var staff = people.filter(function (p) { return p.status !== 'left'; });
  var live = courses.filter(function (c) { return c.status !== 'retired'; });
  var counts = { expired: 0, expiring: 0, missing: 0 };
  var parts = [];
  var lines = [];
  live.forEach(function (course) {
    var list = needs(staff, course, events, nowMs, windowDays);
    list.forEach(function (x) { counts[x.cell.state] += 1; });
    if (list.length) {
      lines.push(course.fields.title + ' (' + course.id + ', ' + validity(course) + '): ' + list.map(function (x) { return needText(x.person, x.cell, nowMs); }).join('; '));
    }
  });
  parts.push(
    staff.length + (staff.length === 1 ? ' person, ' : ' people, ') + live.length + (live.length === 1 ? ' course: ' : ' courses: ') +
      counts.expired + ' lapsed, ' + counts.expiring + ' running out within ' + windowDays + ' days, ' + counts.missing + ' never done.',
  );
  // One list per course, lapsed first: "who needs the refresher this month" is answered from its line alone.
  parts.push(lines.length ? 'Who needs what within ' + windowDays + ' days, by course, lapsed first: ' + lines.join(' | ') + '.' : 'Everyone is current for the next ' + windowDays + ' days.');
  var later = [];
  staff.forEach(function (p) {
    live.forEach(function (course) {
      var c = cell(p, course, events, nowMs, windowDays);
      if (c.required && c.state === 'current') later.push({ who: p.fields.name, what: course.fields.title, at: c.expiresAt });
    });
  });
  later.sort(function (a, b) { return String(a.at).localeCompare(String(b.at)); });
  if (later.length) parts.push('Next to run out after that: ' + later[0].who + "'s " + later[0].what + ' on ' + later[0].at + '.');
  return { expired: counts.expired, expiringSoon: counts.expiring, missing: counts.missing, people: staff.length, summary: parts.join(' ') };
}
function personLine(person, courses, events, nowMs, windowDays) {
  var f = person.fields || {};
  var items = courses
    .filter(function (c) { return c.status !== 'retired'; })
    .map(function (course) {
      var c = cell(person, course, events, nowMs, windowDays);
      if (!c.required && !c.last) return null;
      var cert = c.last && c.last.data.certificate ? ', ' + c.last.data.certificate : '';
      var text =
        c.state === 'missing'
          ? 'not done'
          : c.state === 'done'
            ? 'done ' + c.last.data.completedAt + cert
            : c.state + (c.expiresAt ? ' (valid until ' + c.expiresAt + ')' : '') + cert;
      return course.fields.title + ' ' + text + (c.booking ? ', booked ' + c.booking.data.on : '');
    })
    .filter(Boolean);
  return f.name + ' (' + person.id + ', ' + (f.role || 'no role') + (person.status === 'left' ? ', left' : '') + '): ' + (items.join('; ') || 'no courses apply');
}
function parseQuestions(text) {
  var raw = String(text == null ? '' : text).trim();
  var out = [];
  var skipped = [];
  function add(q, right, wrong) {
    q = String(q || '').trim();
    right = String(right || '').trim();
    wrong = (wrong || []).map(function (w) { return String(w).trim(); }).filter(Boolean);
    if (!q || !right) return false;
    var choices = [right].concat(wrong);
    var shift = out.length % choices.length;
    var rotated = choices.slice(choices.length - shift).concat(choices.slice(0, choices.length - shift));
    out.push({ q: q, choices: rotated, answer: shift });
    return true;
  }
  if (/^\[/.test(raw)) {
    try {
      var parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        parsed.forEach(function (o, i) {
          if (!o || typeof o !== 'object') return skipped.push(i + 1);
          var right = o.answer || o.correct || o.right;
          var wrong = o.wrong || o.distractors || (o.options || o.choices || []).filter(function (c) { return c !== right; });
          if (!add(o.question || o.q, right, wrong)) skipped.push(i + 1);
        });
        return { questions: out, skipped: skipped };
      }
    } catch (e) {
      // Not JSON after all; read it line by line.
    }
  }
  raw.split(/\r?\n/).forEach(function (line, i) {
    var clean = line.replace(/^\s*(?:q?\d{1,2}[.):]|[-*])\s*/i, '').trim();
    if (!clean) return;
    var parts = clean.split('|').map(function (s) { return s.trim(); });
    if (parts.length < 2) {
      var qa = clean.match(/^(.+?\?)\s*(?:answer|a)?\s*[:=-]+\s*(.+)$/i);
      if (qa) parts = [qa[1], qa[2]];
    }
    if (parts.length < 2 || !add(parts[0], parts[1], parts.slice(2))) skipped.push(i + 1);
  });
  return { questions: out, skipped: skipped };
}
// ── training-rules-end ──

const people = rosterStore(gezel.fs, 'people.json', { stages: ['active', 'left'], idPrefix: 'p' });
const courses = rosterStore(gezel.fs, 'courses.json', { stages: ['active', 'retired'], idPrefix: 'c' });
const log = logStore(gezel.fs, 'completions.json');
const quizzes = rosterStore(gezel.fs, 'quizzes.json', { stages: ['ready', 'retired'], idPrefix: 'qz' });
const now = Date.now();
const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 30;
const nameOf = (r: { fields: Record<string, unknown> }) => String(r.fields.name ?? '');
const titleOf = (r: { fields: Record<string, unknown> }) => String(r.fields.title ?? '');

async function resolveCourse(text?: string) {
  const all = await courses.list();
  if (!text) throw new Error("Pass 'course' (id or title). Courses: " + (describe(all, titleOf) || 'none yet; add one with add_course') + '.');
  let hits = matches(all.filter((c) => c.status !== 'retired'), text, titleOf);
  if (!hits.length) hits = matches(all, text, titleOf);
  if (hits.length === 1) return hits[0]!;
  if (hits.length > 1) throw new Error("More than one course matches '" + text + "': " + describe(hits, titleOf) + '. Pass the id.');
  throw new Error("No course matches '" + text + "'. Courses: " + (describe(all, titleOf) || 'none yet; add one with add_course') + '.');
}

async function resolvePeople(text?: string) {
  const all = await people.list();
  if (!text) throw new Error("Pass 'person': a name or id, or several separated by commas.");
  const wanted = String(text).split(/\s*(?:,|;|&|\band\b)\s*/i).map((s) => s.trim()).filter(Boolean);
  const found: typeof all = [];
  for (const one of wanted) {
    let hits = matches(all.filter((p) => p.status !== 'left'), one, nameOf);
    if (!hits.length) hits = matches(all, one, nameOf);
    if (hits.length > 1) throw new Error("More than one person matches '" + one + "': " + describe(hits, nameOf) + '. Pass the id.');
    if (!hits.length) throw new Error("No person matches '" + one + "'. People: " + (describe(all, nameOf) || 'none yet; add them with add_person') + '.');
    if (!found.some((p) => p.id === hits[0]!.id)) found.push(hits[0]!);
  }
  return found;
}

// The tracker's one reminder sits on the next certificate to run out, 14 days ahead of it.
async function remindNextExpiry(): Promise<void> {
  const lead = 14 * DAY_MS;
  const staff = (await people.list()).filter((p) => p.status !== 'left');
  const live = (await courses.list()).filter((c) => c.status !== 'retired');
  const events = await log.list();
  const upcoming: Array<{ title: string; body: string; at: number }> = [];
  for (const p of staff) {
    for (const course of live) {
      const c = cell(p, course, events, now, withinDays);
      if (!c.required || !c.expiresAt || c.booking) continue;
      const at = Date.parse(String(c.expiresAt) + 'T09:00:00') - lead;
      if (at > now) {
        upcoming.push({
          at,
          title: (nameOf(p) + "'s " + titleOf(course)).slice(0, 56) + ' runs out in two weeks',
          body: 'Valid until ' + c.expiresAt + '. Book the refresher from the training tracker.',
        });
      }
    }
  }
  const next = upcoming.sort((a, b) => a.at - b.at)[0];
  try {
    if (!next || next.at - now > 30 * DAY_MS) await gezel.reminder.clear();
    else await gezel.reminder.set({ at: new Date(next.at).toISOString(), title: next.title, body: next.body });
  } catch {
    // Reminders are a convenience; the tracker is the record.
  }
}

let note = '';

if (input.action === 'add_person') {
  if (!input.name || !input.name.trim()) throw new Error("add_person needs 'name'.");
  const name = input.name.trim();
  const startedAt = input.startedAt ? parseDay(input.startedAt, now, 'future') : null;
  if (input.startedAt && !startedAt) throw new Error("startedAt must be a date like '2026-11-09' or a weekday like 'monday'.");
  const status = input.personStatus ? String(input.personStatus).trim().toLowerCase() : '';
  if (status && status !== 'active' && status !== 'left') throw new Error("personStatus must be 'active' or 'left'.");
  const fields: Record<string, unknown> = {
    ...(input.role ? { role: input.role.trim() } : {}),
    ...(startedAt ? { startedAt } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  const existing = (await people.list()).find((p) => nameOf(p).toLowerCase() === name.toLowerCase());
  if (existing) {
    await people.update(existing.id, { fields });
    if (status && status !== existing.status) await people.transition(existing.id, status);
    note = 'Updated ' + name + ' (' + existing.id + ')' + (status === 'left' ? '; they are off the matrix now.' : '.');
  } else {
    const record = await people.add({ status: status || 'active', fields: { name, role: '', ...fields } });
    const needed = (await courses.list()).filter((c) => c.status !== 'retired' && requires(c, record));
    note = 'Added ' + name + ' (' + record.id + ')' + (needed.length ? '; they need ' + needed.map(titleOf).join(', ') + '.' : '.');
  }
} else if (input.action === 'add_course') {
  if (!input.title || !input.title.trim()) throw new Error("add_course needs 'title'.");
  const title = input.title.trim();
  let validMonths: number | undefined;
  if (input.validMonths !== undefined) {
    validMonths = Math.round(Number(input.validMonths));
    if (!(validMonths >= 0)) throw new Error('validMonths must be 0 (never expires) or more.');
  }
  const fields: Record<string, unknown> = {
    ...(validMonths !== undefined ? { validMonths } : {}),
    ...(input.requiredFor ? { requiredFor: input.requiredFor.trim() } : {}),
    ...(input.provider ? { provider: input.provider.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  const existing = (await courses.list()).find((c) => titleOf(c).toLowerCase() === title.toLowerCase());
  if (existing) {
    await courses.update(existing.id, { fields });
    note = 'Updated ' + title + ' (' + existing.id + ').';
  } else {
    const record = await courses.add({ status: 'active', fields: { title, validMonths: 0, requiredFor: 'everyone', ...fields } });
    note = 'Added ' + title + ' (' + record.id + '), ' + validity(record) + ', for ' + String(record.fields.requiredFor) + '.';
  }
} else if (input.action === 'complete') {
  const course = await resolveCourse(input.course);
  const who = await resolvePeople(input.person);
  const completedAt = input.completedAt ? parseDay(input.completedAt, now, 'past') : localDay(now);
  if (!completedAt) throw new Error("completedAt must be a date like '2026-11-02', or 'today'.");
  const months = Number(course.fields.validMonths) || 0;
  const expiresAt = months > 0 ? addMonths(completedAt, months) : null;
  const certificate = input.certificate ? input.certificate.trim() : '';
  for (const p of who) {
    await log.append({
      kind: 'completed',
      note: input.note ? input.note.trim() : certificate ? 'Certificate ' + certificate + '.' : 'Completed.',
      data: { personId: p.id, courseId: course.id, completedAt, expiresAt, ...(certificate ? { certificate } : {}) },
    });
  }
  note =
    who.map(nameOf).join(', ') + ' completed ' + titleOf(course) + ' on ' + completedAt +
    (expiresAt ? '; valid until ' + expiresAt : '; it does not expire') + (certificate ? ', certificate ' + certificate : '') + '.';
} else if (input.action === 'book') {
  const course = await resolveCourse(input.course);
  const on = parseDay(input.on, now, 'future');
  if (!on) throw new Error("book needs 'on': a date like '2026-11-12' or a weekday like 'thursday'.");
  const events = await log.list();
  let who: Awaited<ReturnType<typeof resolvePeople>> = [];
  if (input.everyoneDue) {
    const staff = (await people.list()).filter((p) => p.status !== 'left');
    who = needs(staff, course, events, now, withinDays).filter((x: { cell: { booking: unknown } }) => !x.cell.booking).map((x: { person: (typeof staff)[number] }) => x.person);
  } else {
    who = await resolvePeople(input.person);
  }
  const fresh = who.filter((p) => !eventsFor(events, 'booked', p.id, course.id).some((e: { data: { on: string } }) => e.data.on === on));
  for (const p of fresh) {
    await log.append({ kind: 'booked', note: input.note ? input.note.trim() : 'Booked.', data: { personId: p.id, courseId: course.id, on } });
  }
  note = fresh.length
    ? 'Booked ' + titleOf(course) + ' on ' + dayName(on) + ' ' + on + ' for ' + fresh.map(nameOf).join(', ') + '.'
    : input.everyoneDue
      ? 'Nobody else needs ' + titleOf(course) + ' within ' + withinDays + ' days; nothing new booked.'
      : 'Already booked; nothing changed.';
} else if (input.action === 'save_quiz') {
  if (!input.questions) throw new Error("save_quiz needs 'questions', one per line: 'Question? | right answer | wrong answer | wrong answer'.");
  const parsed = parseQuestions(input.questions);
  if (parsed.questions.length < 3) {
    throw new Error("A quiz needs at least 3 questions, one per line: 'Question? | right answer | wrong answer | wrong answer'. Read " + parsed.questions.length + '.');
  }
  const course = input.course ? await resolveCourse(input.course) : null;
  const title = (input.title && input.title.trim()) || (course ? titleOf(course) + ' quiz' : 'Quiz');
  const fields: Record<string, unknown> = {
    title,
    questions: parsed.questions,
    ...(course ? { courseId: course.id, courseTitle: titleOf(course) } : {}),
    ...(input.source ? { source: input.source.trim() } : {}),
  };
  const existing = (await quizzes.list()).find((q) => titleOf(q).toLowerCase() === title.toLowerCase());
  if (existing) await quizzes.update(existing.id, { fields });
  else await quizzes.add({ status: 'ready', fields });
  note =
    'Saved the quiz ' + title + ' with ' + parsed.questions.length + ' questions' + (course ? ' for ' + titleOf(course) : '') +
    (parsed.skipped.length ? '; skipped line ' + parsed.skipped.join(', ') + " (write them as 'Question? | right | wrong | wrong')" : '') + '.';
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, add_person, add_course, complete, book, save_quiz, or list.");
}

const allPeople = await people.list();
const allCourses = await courses.list();
const events = await log.list();
const view = picture(allPeople, allCourses, events, now, withinDays);
await remindNextExpiry();

let summary = (note ? note + ' ' : '') + view.summary;
if (input.action === 'list') {
  const wanted = input.person ? await resolvePeople(input.person) : allPeople;
  summary = wanted.map((p) => personLine(p, allCourses, events, now, withinDays)).join('\n') || 'Nobody on the tracker yet.';
}
gezel.output({ expired: view.expired, expiringSoon: view.expiringSoon, missing: view.missing, people: view.people, summary });

